/**
 * Typed access to the tour snapshots generated by `scripts/sync-tours-snapshot.mjs`.
 * The JSON files are copies of the live pages and must not be edited by hand;
 * each one is validated here at build time so a bad file fails the build.
 */
import "server-only";
import { z } from "zod";
import tourIndex from "./tours/index.json";

const inlineRun = z.object({ text: z.string(), bold: z.boolean().optional(), href: z.string().optional() });
export type InlineRun = z.infer<typeof inlineRun>;

const block = z.discriminatedUnion("type", [
  z.object({ type: z.literal("p"), content: z.array(inlineRun) }),
  z.object({ type: z.literal("list"), items: z.array(z.array(inlineRun)) }),
  z.object({ type: z.literal("fact"), label: z.string(), value: z.string() }),
  z.object({ type: z.literal("label"), text: z.string() }),
  z.object({ type: z.literal("heading"), text: z.string() }),
  z.object({
    type: z.literal("table"),
    caption: z.string().optional(),
    head: z.array(z.string()),
    rows: z.array(z.array(z.string())),
  }),
]);
export type ContentBlock = z.infer<typeof block>;

const genericSection = z.object({ kind: z.literal("generic"), title: z.string(), blocks: z.array(block) });
export type GenericSection = z.infer<typeof genericSection>;

const itineraryDay = z.object({ title: z.string().optional(), items: z.array(z.string()), notes: z.array(z.string()) });
export type ItineraryDay = z.infer<typeof itineraryDay>;

const hotelTier = z.object({
  name: z.string(),
  stays: z.array(z.object({ place: z.string(), names: z.string() })),
});
export type HotelTier = z.infer<typeof hotelTier>;

const mainSection = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("includes"), title: z.string(), items: z.array(z.string()) }),
  z.object({ kind: z.literal("highlights"), title: z.string(), items: z.array(z.string()) }),
  z.object({ kind: z.literal("itinerary"), title: z.string(), days: z.array(itineraryDay) }),
  z.object({ kind: z.literal("hotels"), title: z.string(), tiers: z.array(hotelTier) }),
  genericSection,
]);
export type MainSection = z.infer<typeof mainSection>;

const priceTier = z.object({ name: z.string().optional(), amount: z.string(), unit: z.string() });
export type PriceTier = z.infer<typeof priceTier>;

const tourSchema = z.object({
  slug: z.string(),
  url: z.string(),
  seo: z.object({ title: z.string(), description: z.string(), ogImage: z.string().nullable() }),
  title: z.string().min(1),
  duration: z.object({ label: z.string(), value: z.string() }).nullable(),
  gallery: z.array(z.object({ src: z.string(), alt: z.string() })),
  main: z.array(mainSection),
  price: z.object({ tiers: z.array(priceTier), note: z.string().optional(), enquireLabel: z.string().optional() }),
  inclusions: z
    .object({
      includedLabel: z.string(),
      excludedLabel: z.string(),
      included: z.array(z.string()),
      excluded: z.array(z.string()),
    })
    .nullable(),
  policies: z.array(genericSection),
  related: z
    .object({
      title: z.string(),
      items: z.array(
        z.object({
          href: z.string(),
          title: z.string(),
          duration: z.string(),
          price: z.object({ label: z.string(), amount: z.string(), unit: z.string() }).optional(),
          image: z.string().nullable(),
        }),
      ),
    })
    .nullable(),
  faq: z
    .object({
      title: z.string(),
      items: z.array(z.object({ question: z.string(), answer: z.array(inlineRun) })),
    })
    .nullable(),
  reviews: z
    .object({
      title: z.string(),
      items: z.array(z.object({ name: z.string(), rating: z.number().int().min(0).max(5), text: z.string() })),
    })
    .nullable(),
  enquiry: z.object({
    formTitle: z.string(),
    cf7FormId: z.string().nullable(),
    adultsMax: z.number().nullable(),
    childrenMax: z.number().nullable(),
  }),
});
export type Tour = z.infer<typeof tourSchema>;

const indexSchema = z.object({
  tours: z.array(
    z.object({
      slug: z.string().regex(/^[a-z0-9-]+$/),
      title: z.string(),
      duration: z.string().nullable(),
      price: priceTier.nullable(),
      image: z.string().nullable(),
    }),
  ),
});

const index = indexSchema.parse(tourIndex);
const knownSlugs = new Set(index.tours.map((t) => t.slug));

export function listTourSlugs(): string[] {
  return index.tours.map((t) => t.slug);
}

/** Loads one tour. Returns null for unknown slugs (the slug is checked before any file is touched). */
export async function getTour(slug: string): Promise<Tour | null> {
  if (!knownSlugs.has(slug)) return null;
  const data = (await import(`./tours/${slug}.json`)).default;
  return tourSchema.parse(data);
}

/** Title of a known tour — used server-side to label enquiries without trusting the browser. */
export function tourTitle(slug: string): string | null {
  return index.tours.find((t) => t.slug === slug)?.title ?? null;
}
